//! The attribute member a Context Producer may not supply.
//!
//! ETSI GS CIM 009 v1.9.1 closes eight data type definitions with the same
//! sentence about their "Output only members": clause 5.2.5 (Property),
//! 5.2.6 (Relationship), 5.2.7 (`GeoProperty`), 5.2.32 (`LanguageProperty`),
//! 5.2.35 (`VocabProperty`), 5.2.36 (`ListProperty`), 5.2.37
//! (`ListRelationship`) and 5.2.38 (`JsonProperty`) each state that they "are
//! read-only and shall be generated by NGSI-LD implementations; they shall not
//! be provided by Context Producers, and if provided in update or create
//! operations shall be ignored".
//!
//! Each family has exactly one such member — the `previous…` spelling of its
//! own value member, which clause 5.2.14.1 says a notification carries only
//! when `showChanges` was explicitly requested — and
//! [`AttributeType::previous_key`] already names it.
//!
//! Ignored, not refused. A create or update carrying one is a valid request
//! and is answered as one; the member simply does not become part of the
//! entity. That distinction matters: a stored `previousValue` a client wrote
//! is a value no change of the broker's ever produced, and a later
//! `showChanges` notification would present it to subscribers as the state
//! that preceded a change it never preceded.
//!
//! A `previous…` member belonging to some *other* family is a different
//! failure — clause 4.5.2.2 and its siblings prohibit it outright — and
//! [`crate::family_member_admission`] owns that one.

use andromeda_ngsi_ld_lexicon::attribute_type::AttributeType;
use serde_json::{Map, Value};

/// Drop the output-only member of one attribute instance's own family.
///
/// The instance is left otherwise untouched, including any `previous…` member
/// of another family: that one is invalid rather than ignorable.
pub fn discard_output_only_member(instance: &mut Map<String, Value>, attribute_type: AttributeType) {
    instance.remove(attribute_type.previous_key());
}

#[cfg(test)]
mod tests {
    use crate::output_only_member::discard_output_only_member;
    use andromeda_ngsi_ld_lexicon::attribute_type::AttributeType;
    use serde_json::{Map, Value, json};

    /// The instance as a mutable object map, which is the shape normalization
    /// hands this function.
    fn instance(value: &Value) -> Map<String, Value> {
        value.as_object().expect("the fixture is an object").clone() // clone: the test owns a mutable copy of its fixture
    }

    /// Clause 5.2.5: a `previousValue` a Context Producer supplied is ignored.
    #[test]
    fn a_property_instance_loses_the_previous_value_it_was_given() {
        let mut property = instance(&json!({"type": "Property", "value": 42, "previousValue": 9, "observedAt": "2024-01-01T00:00:00Z"}));

        discard_output_only_member(&mut property, AttributeType::Property);

        pretty_assertions::assert_eq!(
            Value::Object(property),
            json!({"type": "Property", "value": 42, "observedAt": "2024-01-01T00:00:00Z"})
        );
    }

    /// Clauses 5.2.6, 5.2.7, 5.2.32, 5.2.35, 5.2.36, 5.2.37 and 5.2.38 say the
    /// same of each remaining family's own output-only member.
    #[test]
    fn every_family_loses_its_own_output_only_member() {
        for attribute_type in AttributeType::ALL {
            let mut attribute = instance(&json!({
                "type": attribute_type.to_string(),
                attribute_type.compact_value_key(): "kept",
                attribute_type.previous_key(): "forged",
            }));

            discard_output_only_member(&mut attribute, attribute_type);

            assert!(!attribute.contains_key(attribute_type.previous_key()), "{attribute_type}: {attribute:?}");
            assert!(attribute.contains_key(attribute_type.compact_value_key()), "{attribute_type}: {attribute:?}");
        }
    }

    /// Another family's `previous…` member is prohibited rather than ignored
    /// (clause 4.5.3.2), so it survives to the validator that refuses it.
    #[test]
    fn another_familys_output_only_member_is_left_for_the_validator_to_refuse() {
        let mut relationship = instance(&json!({"type": "Relationship", "object": "urn:ngsi-ld:Site:1", "previousValue": 9}));

        discard_output_only_member(&mut relationship, AttributeType::Relationship);

        assert!(relationship.contains_key("previousValue"), "{relationship:?}");
    }
}
